// Написан autotest-writer вручную (3 роли: admin + user4 + new02 — генератор не умеет). spec: .qa/e2e/specs/gifts.md 5.1–5.2 · кейсы .qa/tests/gifts/GIFT-16, GIFT-17
// Тикеты #99ff3d (грант админа виден в магазине без перезапуска) и #fc49b2 (экран получения подарка). Раунд 12, 18.11.2026.
// ПРЕДУСЛОВИЯ (не создаются тестом): у user4 нет бесплатных подарков; чат user4↔new02 есть; у new02 «קבלת מתנות» включено; нет запрета «אפשר לשלוח עוד אחרי ש… יענה».
// ГРАНТ «הענקת מתנה» тест выдаёт сам — запускать только с разрешением пользователя на грант (как gifts 4.1). Тест 5.2 тратит этот грант (возврат состояния).
// УБОРКА: подарок и сообщения удалить нельзя — остаются в чате user4↔new02 (аннотация cleanup). В конце new02 отвечает user4 (снимает запрет «до ответа»).
// НЕ проверен на живой странице: тексты экрана подарка («… שלח/ה לך מתנה», «להשיב ל…», «לפרופיל של …», ✕) — со слов брифа/видео дизайнера; проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { userIdOf } from '../location-map/map-helpers';
import { ADMIN_URL, adminAs, closeAdmin } from '../moderation-menu/mod-helpers';
import { N2, U4, phone, openChat, openSendScreen, giftMessageField, freeSendButton, awaitingReplyHint } from './gifts-helpers';

const FREE_STRIP = /יש לך\s*·?\s*מתנה חינם אחת/;

async function sendText(page: Page, text: string) {
  await page.getByRole('textbox', { name: 'כתוב הודעה' }).fill(text);
  const w = page.waitForResponse((x) => x.url().includes('/rest/v1/messages') && x.request().method() === 'POST');
  await page.getByRole('button', { name: 'שליחה' }).click();
  expect((await w).ok(), `сообщение «${text}» отправлено`).toBeTruthy();
}

// Чат → 🎁 → магазин подарков (лист «מתנה ל…»), не заходя на экран отправки.
async function openStore(page: Page, partner: string) {
  await openChat(page, partner);
  await page.getByRole('button', { name: /מתנה|🎁|gift/i }).first().click();
  await expect(page.getByText(new RegExp(`מתנה ל־?\\s?${partner}`)).or(page.getByText('ורד זהב')).first()).toBeVisible({ timeout: 20_000 });
}

test.describe('Подарки: грант админа без перезапуска + экран получения подарка', () => {
  test.describe.configure({ mode: 'serial', timeout: 300_000 });

  let granted = false;
  let sentMsg = '';

  test('Грант админа user4 виден в магазине подарков при повторном открытии, без перезагрузки @iphone @data (#99ff3d)', async ({ asUser, browser }) => {
    const u4 = await asUser('user4');
    const admin = await adminAs(browser);
    try {
      await phone(u4);
      // 1. Магазин без гранта: нет «יש לך · מתנה חינם אחת» и меток «חינם».
      await openStore(u4, N2);
      await expect(u4.getByText(FREE_STRIP), 'ОКРУЖЕНИЕ: у user4 уже есть бесплатный подарок — потрать его (gifts 5.2 / вручную) и повтори').toHaveCount(0);
      await expect(u4.getByText(/^חינם$/)).toHaveCount(0);
      await u4.getByRole('button', { name: /סגירה|חזרה|close|back/i }).first().click();

      // 2. Админка: «הענקת מתנה» user4 (страница user4 не перезагружается).
      await admin.goto(`${ADMIN_URL}/subscriptions/${userIdOf('user4')}`);
      await expect(admin.getByRole('button', { name: 'הענקת מתנה' }).first()).toBeVisible({ timeout: 30_000 });
      await admin.getByRole('button', { name: 'הענקת מתנה' }).first().click();
      await admin.getByRole('button', { name: 'הענקה' }).last().click();
      granted = true;
      await expect(admin.getByRole('button', { name: 'הענקה' })).toHaveCount(0);

      // 3. user4 открывает магазин снова тем же путём — полоса и «חינם» уже есть (#99ff3d «מה רצוי»).
      await expect(async () => {
        await openStore(u4, N2);
        await expect(u4.getByText(FREE_STRIP)).toBeVisible({ timeout: 5_000 });
      }).toPass({ timeout: 60_000 });
      await expect(u4.getByText(/חינם/).first()).toBeVisible();
    } finally {
      if (granted) test.info().annotations.push({ type: 'cleanup', description: 'user4 получил +1 бесплатный подарок; тратится в следующем тесте (5.2). Если 5.2 не прошёл — потрать вручную.' });
      await saveSession(u4, 'user4');
      await closeAdmin(admin);
    }
  });

  test('Бесплатный подарок user4→new02: у получателя полноэкранный экран подарка, финал статичен до ✕, повтора нет @iphone @data (#fc49b2)', async ({ asUser }) => {
    test.skip(!granted, 'нет гранта: 5.1 не выдал бесплатный подарок user4');
    const s = await asUser('user4');
    const r = await asUser('new02');
    const msg = `QA-AUTO fc49b2 ${Date.now()}`;
    let sent = false;
    let replied = false;
    try {
      for (const p of [s, r]) await phone(p);
      // new02 стоит в списке «הודעות», в чат не заходит.
      await r.goto('/matches');
      await expect(r.getByText(U4, { exact: true }).first()).toBeVisible({ timeout: 20_000 });

      // 1. user4 отправляет бесплатный подарок с сообщением.
      await openChat(s, N2);
      await openSendScreen(s, N2);
      await expect(awaitingReplyHint(s, N2), 'ОКРУЖЕНИЕ: прошлый подарок без ответа — ответь вручную new02 → user4').toHaveCount(0);
      const btn = freeSendButton(s);
      await expect(btn, 'ОКРУЖЕНИЕ: у user4 нет бесплатного подарка').toBeEnabled({ timeout: 15_000 });
      await giftMessageField(s).fill(msg);
      const wait = s.waitForResponse((x) => x.url().includes('/rpc/send_gift') && x.request().method() === 'POST');
      await btn.click();
      const res = await wait;
      expect(res.ok(), `send_gift: ${res.status()} ${await res.text()}`).toBeTruthy();
      sent = true;
      await expect(s.getByText('המתנה נשלחה').first()).toBeVisible();

      // 2. new02 открывает чат из списка → экран подарка.
      await expect(async () => {
        await r.goto('/matches');
        await r.getByText(U4, { exact: true }).last().click();
        await r.waitForURL(/\/chat\//);
        await expect(r.getByText(/לך מתנה/).first()).toBeVisible({ timeout: 8_000 });
      }).toPass({ timeout: 90_000 });

      // 3. Финал: заголовок «… שלח/ה לך מתנה», сообщение, «להשיב ל…», «לפרופיל של …», ✕ — ждём до 15 с (анимация ~4 с).
      const reply = r.getByRole('button', { name: /להשיב ל/ });
      await expect(reply).toBeVisible({ timeout: 15_000 });
      await expect(r.getByText(msg).first()).toBeVisible();
      await expect(r.getByRole('button', { name: /לפרופיל של/ })).toBeVisible();
      const close = r.getByRole('button', { name: /סגירה|✕|close/i }).first();
      await expect(close).toBeVisible();

      // Финал статичен: в чат сам не возвращается (выдержка 2.5 с — намеренная, проверка «не уходит сам»).
      await r.evaluate(() => new Promise((res) => setTimeout(res, 2500)));
      await expect(reply).toBeVisible();

      // У отправителя экрана подарка нет.
      await expect(s.getByRole('button', { name: /להשיב ל/ })).toHaveCount(0);

      // 4. ✕ → чат; повторный вход и обновление — экран не появляется (1 раз на подарок).
      await close.click();
      await expect(r.getByRole('textbox', { name: 'כתוב הודעה' })).toBeVisible();
      await openChat(r, U4);
      await expect(r.getByRole('button', { name: /להשיב ל/ })).toHaveCount(0);
      await r.reload();
      await expect(r.getByRole('textbox', { name: 'כתוב הודעה' })).toBeVisible();
      await expect(r.getByRole('button', { name: /להשיב ל/ })).toHaveCount(0);

      // 5. Очистка: new02 отвечает user4 — снимает запрет «до ответа».
      await sendText(r, `${msg} reply`);
      replied = true;
      sentMsg = msg;
    } finally {
      if (sent) test.info().annotations.push({ type: 'cleanup', description: `подарок user4→new02 «${msg}»${replied ? ' + ответ new02' : ' (new02 НЕ ответил — ответь вручную)'}; грант user4 потрачен; удалить нельзя — список чистки` });
      await saveSession(s, 'user4');
      await saveSession(r, 'new02');
    }
  });
});
